import {readFile,writeFile} from 'node:fs/promises';
export const modules=['limits','xml','zip','core','report','worker'];
export async function workerSource(){const parts=[];for(const name of modules){const text=await readFile(`src/${name}.mjs`,'utf8');parts.push(text.replace(/^import .*;\s*$/gm,'').replace(/^export \{[^}]+\};\s*$/gm,'').replace(/\bexport (?=(?:const|class|function|async function)\b)/g,''));}return '"use strict";\n'+parts.join('\n');}
export async function writeWorker(){await writeFile('src/worker-source.mjs','// Generated by scripts/worker-bundle.mjs.\nexport const WORKER_SOURCE='+JSON.stringify(await workerSource())+';\n');}
